    const workflowTitle = String(payload.workflow_title || payload.workflowTitle || workflowRef.replace(/\.json$/i, '') || 'ComfyUI 工作流').trim();
    const fields = Array.isArray(payload.fields) ? JSON.parse(JSON.stringify(payload.fields)) : [];
