    const providerExists = requestedProvider && (apiProviders || []).some(item => item?.id === requestedProvider && item?.enabled !== false);
    const copyCompatibleFields = (skip = new Set()) => Object.entries(requested).forEach(([key, value]) => {
        if(!skip.has(key) && value !== undefined) next[key] = value;
    });
    if(requestedEngine === 'comfy'){
        const workflow = String(requested.comfyWorkflow || '').trim();
        if(workflow && (comfyWorkflows || []).some(item => item?.name === workflow)){
            next.engine = 'comfy';
            next.comfyWorkflow = workflow;
            if(requested.comfyMode) next.comfyMode = requested.comfyMode;
            copyCompatibleFields(new Set(['engine','provider_id','model','comfyWorkflow','comfyMode']));
        } else if(workflow){
            warnings.push('案例工作流不存在，已保留当前工作流');
        }
    } else if(requestedEngine === 'api' || requestedProvider || requestedModel){
        if(requestedEngine === 'api') next.engine = 'api';
        if(requestedProvider){
            if(providerExists) next.provider_id = requestedProvider;
            else warnings.push('案例平台不存在，已保留当前平台');
        }
        const modelProvider = requestedProvider && providerExists ? requestedProvider : String(next.provider_id || '').trim();
        const availableModels = providerImageModels(modelProvider).map(value => String(value || ''));
        if(requestedModel && (!availableModels.length || availableModels.includes(requestedModel))) next.model = requestedModel;
        else if(requestedModel) warnings.push('案例模型不存在，已保留当前模型');
        copyCompatibleFields(new Set(['engine','provider_id','model','comfyWorkflow','comfyMode']));
    } else {
        copyCompatibleFields();
    }
    clearVolcengineSelectionOutsideVolcengine(next);
    normalizeSmartVideoModeSettings(next, true);
