    if(!Number.isFinite(width) || width <= 24 || !Number.isFinite(height) || height <= 24) return null;
    const completedCount = Math.max(0, Number(count) || 0);
    const remainingCount = Math.max(pendingCount, taskCount);
    const total = Math.max(1, completedCount, remainingCount + completedCount);
    const cols = total <= 1 ? 1 : Math.min(4, Math.max(2, Math.ceil(Math.sqrt(total))));
    const rows = Math.ceil(total / cols);
