function parseSizeValue(value){
    const match = String(value || '').trim().match(/^(\d+)\s*[xX*]\s*(\d+)$/);
    return match ? {width:match[1], height:match[2]} : null;
}
function parseRatioValue(value){
    const raw = String(value || '').trim();
    const parts = raw.includes(':') ? raw.split(':') : raw.split(/[xX*]/);
    if(parts.length !== 2) return 0;
    const w = Number(parts[0]);
    const h = Number(parts[1]);
    return w > 0 && h > 0 ? w / h : 0;
}
function apiImageSize(ratioValue, resolutionValue, customRatioValue='', customSizeValue=''){
    if(resolutionValue === 'auto') return 'auto';
    if(resolutionValue === 'custom') return String(customSizeValue || '').trim();
    const resolutionKey = resolutionValue || '1k';
    if(ratioValue === 'custom' || ratioValue === 'source'){
        const parsed = parseRatioValue(customRatioValue);
        const longSide = RES_LONG_SIDE[resolutionKey] || 1024;
        if(parsed){
            const pixelLimit = RES_PIXEL_LIMIT[resolutionKey] || (longSide * longSide);
            const rawWidth = parsed >= 1 ? longSide : Math.min(longSide * parsed, Math.sqrt(pixelLimit * parsed));
            const rawHeight = parsed >= 1 ? Math.min(longSide / parsed, Math.sqrt(pixelLimit / parsed)) : longSide;
            const width = Math.floor(rawWidth / 16) * 16;
            const height = Math.floor(rawHeight / 16) * 16;
            return `${Math.max(64, width)}x${Math.max(64, height)}`;
        }
    }
    const extendedSize = SMART_EXTENDED_SIZE_MAP[ratioValue]?.[resolutionKey];
    if(extendedSize) return extendedSize;
    const ratioKey = ratioValue && SIZE_MAP[ratioValue] ? ratioValue : 'square';
    return SIZE_MAP[ratioKey]?.[resolutionKey] || SIZE_MAP.square[resolutionKey] || SIZE_MAP.square['1k'];
}
function normalizeGptImage2Size(value){
    const parsed = parseSizeValue(value);
    if(!parsed) return value || 'auto';
    let width = Number(parsed.width);
    let height = Number(parsed.height);
    if(!width || !height) return value || 'auto';
    const valid = width % 16 === 0 && height % 16 === 0
        && Math.max(width, height) <= GPT_IMAGE2_MAX_EDGE
        && width * height >= GPT_IMAGE2_MIN_PIXELS
        && width * height <= GPT_IMAGE2_MAX_PIXELS
        && Math.max(width / height, height / width) <= 3;
    if(valid){
        return `${width}x${height}`;
    }
    const ratio = width / height;
    if(ratio > 3) width = height * 3;
    else if(ratio < 1 / 3) height = width * 3;
    const scale = Math.min(
        1,
        GPT_IMAGE2_MAX_EDGE / Math.max(width, height),
        Math.sqrt(GPT_IMAGE2_MAX_PIXELS / Math.max(1, width * height))
    );
    width = Math.max(16, Math.floor((width * scale) / 16) * 16);
    height = Math.max(16, Math.floor((height * scale) / 16) * 16);
    if(width * height < GPT_IMAGE2_MIN_PIXELS){
        const grow = Math.sqrt(GPT_IMAGE2_MIN_PIXELS / Math.max(1, width * height));
        width = Math.ceil((width * grow) / 16) * 16;
        height = Math.ceil((height * grow) / 16) * 16;
    }
    if(width > height * 3) width = Math.max(16, Math.floor(height * 3 / 16) * 16);
    else if(height > width * 3) height = Math.max(16, Math.floor(width * 3 / 16) * 16);
    while(Math.max(width, height) > GPT_IMAGE2_MAX_EDGE || width * height > GPT_IMAGE2_MAX_PIXELS){
        if(width >= height) width = Math.max(16, width - 16);
        else height = Math.max(16, height - 16);
    }
    if(width * height < GPT_IMAGE2_MIN_PIXELS){
        const grow = Math.sqrt(GPT_IMAGE2_MIN_PIXELS / Math.max(1, width * height));
        width = Math.max(16, Math.ceil(width * grow / 16) * 16);
        height = Math.max(16, Math.ceil(height * grow / 16) * 16);
        while(Math.max(width, height) > GPT_IMAGE2_MAX_EDGE || width * height > GPT_IMAGE2_MAX_PIXELS){
            if(width >= height) width = Math.max(16, width - 16);
            else height = Math.max(16, height - 16);
        }
    }
    return `${width}x${height}`;
}
function normalizeApiSizeSettings(prefix=''){
    const ratioKey = prefix ? `${prefix}Ratio` : 'ratio';
    const resKey = prefix ? `${prefix}Resolution` : 'resolution';
    const allowAuto = !prefix && settings.engine === 'api' && settings.apiKind !== 'video' && isGptImageAutoSizeModel(settings.model);
    if(!settings[resKey]) settings[resKey] = allowAuto ? defaultSmartApiResolution(settings.model) : '1k';
    if(!allowAuto && settings[resKey] === 'auto') settings[resKey] = '1k';
    if(settings[resKey] === 'auto' && !settings[ratioKey]) settings[ratioKey] = 'square';
    if(!prefix && settings.engine === 'api' && settings.apiKind !== 'video'
        && !['custom','source'].includes(settings[ratioKey])
        && !smartRatioOptions('', false).some(([value]) => value === settings[ratioKey])){
        settings[ratioKey] = 'square';
    }
}
async function ensureComfyWorkflow(name){
    if(!name) return null;
    const cached = comfyWorkflowCache[name];
    if(cached && !cached._canvasFallback) return cached;
    const data = await fetch(`/api/workflows/${encodeURIComponent(name)}`).then(r => r.ok ? r.json() : null).catch(() => null);
    if(data) comfyWorkflowCache[name] = data;
    return data || cached || null;
}
