function comfyOptionLabel(field, option){
    const raw = String(option ?? '');
    const fieldKeys = [field?.input, String(field?.id || '').split(':').pop(), field?.name]
        .map(value => String(value || '').trim().toLowerCase());
    const fieldKey = fieldKeys.map(key => COMFY_OPTION_FIELD_ALIASES[key] || key).find(key => COMFY_OPTION_LABELS[key]);
    const labels = COMFY_OPTION_LABELS[fieldKey];
    if(!labels) return raw;
    const match = Object.entries(labels).find(([value]) => value.toLowerCase() === raw.toLowerCase());
    return match?.[1] || raw;
}
function mergeComfyWorkflowCatalog(workflows=[], appEntries=[]){
    const merged = new Map();
    const add = (raw, source='workflow') => {
        if(!raw || typeof raw !== 'object') return;
        // /api/workflows 使用 name；ComfyUI 应用库使用 workflow。优先使用可执行的
        // workflow 路径，这样应用库中已经准备好的 custom/app_*.json 可以直接复用
        // 现有 /api/canvas-comfy-tasks 执行链路。
        const name = String(raw.name || raw.workflow || raw.workflow_ref || '').trim();
        if(!name || !/\.json$/i.test(name)) return;
        const previous = merged.get(name) || {};
        const fields = Array.isArray(raw.fields) ? raw.fields : previous.fields;
        const appEntry = source === 'app' || raw.entry_type === 'app';
        const title = String(raw.title || previous.title || name.replace(/\.json$/i, '')).trim();
        merged.set(name, {
            ...previous,
            ...raw,
            name,
            title,
            field_count: Math.max(0, Number(raw.field_count) || 0, Number(previous.field_count) || 0, Array.isArray(fields) ? fields.length : 0),
            fields: Array.isArray(fields) ? fields : [],
            appId: String(raw.id || raw.app_id || previous.appId || '').trim(),
            entryType: appEntry ? 'app' : (previous.entryType || 'workflow'),
            sourceKind: appEntry ? 'app-library' : (previous.sourceKind || 'workflow-library'),
            readiness: raw.readiness && typeof raw.readiness === 'object' ? raw.readiness : (previous.readiness || {}),
            workflowSource: String(raw.workflow_source || previous.workflowSource || '').trim(),
        });
    };
    (Array.isArray(workflows) ? workflows : []).forEach(item => add(item, 'workflow'));
    (Array.isArray(appEntries) ? appEntries : []).forEach(item => add(item, 'app'));
    return [...merged.values()].sort((a, b) => String(a.title || a.name).localeCompare(String(b.title || b.name), 'zh-CN'));
}
async function refreshSavedComfyWorkflowFields(){
    const stale = nodes.filter(node => {
        if(!isSmartComfyWorkflowNode(node) || !node.workflowRef) return false;
        const entry = comfyWorkflows.find(item => item.name === node.workflowRef);
        if(!entry) return false;
        if(Number(entry.field_count) > (node.workflowFields || []).length) return true;
        return (entry.fields || []).some(field => field?.preset_controls?.length
            && !(node.workflowFields || []).find(saved => saved.id === field.id)?.preset_schema_complete);
    });
    if(!stale.length) return;
    const names = [...new Set(stale.map(node => node.workflowRef))];
    const details = await Promise.all(names.map(async name => {
        delete comfyWorkflowCache[name];
        return [name, await ensureComfyWorkflow(name)];
    }));
    let changed = false;
    details.forEach(([name, data]) => {
        const fields = data?.config?.fields;
        if(!Array.isArray(fields)) return;
        stale.filter(node => node.workflowRef === name && nodes.includes(node)).forEach(node => {
            if(fields.length < (node.workflowFields || []).length) return;
            node.workflowFields = JSON.parse(JSON.stringify(fields));
            if(node.comfyAutoSize !== false) node.h = Math.max(Number(node.h) || 0, comfyWorkflowNodeDefaultHeight(fields));
            normalizeSmartComfyWorkflowNode(node);
            changed = true;
        });
    });
    if(!changed) return;
    const subject = activeSettingsSubject();
    if(isSmartComfyWorkflowNode(subject)) settings = cloneSmartSettings(smartSettingsForNode(subject));
    renderDynamicParams();
    render();
    scheduleSave();
}
