function closePreviewImageContextMenu(){
    const menu = document.getElementById('previewImageContextMenu');
    if(!menu) return;
    menu.hidden = true;
    menu.style.left = '';
    menu.style.top = '';
}
function openPreviewImageContextMenu(event){
    const image = currentEditImage().image;
    const menu = document.getElementById('previewImageContextMenu');
    if(!menu || imageEditMode !== 'preview' || !image?.url || panoramaState.enabled) return;
    event.preventDefault();
    event.stopPropagation();
    menu.hidden = false;
    const margin = 8;
    const maxLeft = Math.max(margin, window.innerWidth - menu.offsetWidth - margin);
    const maxTop = Math.max(margin, window.innerHeight - menu.offsetHeight - margin);
    menu.style.left = `${Math.min(Math.max(margin, event.clientX), maxLeft)}px`;
    menu.style.top = `${Math.min(Math.max(margin, event.clientY), maxTop)}px`;
    menu.querySelector('button')?.focus({preventScroll:true});
}
