    const marker = /^(?:(?:第\s*)?(\d{1,3})\s*(?:屏|页|段)|屏幕?\s*(\d{1,3})|(?:screen|page|slide)\s*(\d{1,3})|[（(]\s*(\d{1,3})\s*[）)]|(\d{1,3})\s*(?=[、.)：:\-—|｜丨·]))\s*(?:[、.)：:\-—|｜丨·]\s*)?(.*)$/i;
    const lines = raw.split('\n');
