const AGENT_SKILL_LIBRARY_KEY = 'smart_canvas_agent_skill_library_v1';
const AGENT_SKILL_FAVORITES_KEY = 'smart_canvas_agent_skill_favorites_v1';
let agentSkillLibraryCache = null;
let agentSkillLibraryLoaded = false;
let agentSkillLibraryLoading = null;
function agentSkillLibrary(){
    if(Array.isArray(agentSkillLibraryCache)) return agentSkillLibraryCache;
    try {
        const parsed = JSON.parse(localStorage.getItem(AGENT_SKILL_LIBRARY_KEY) || '[]');
        agentSkillLibraryCache = Array.isArray(parsed) ? parsed.filter(skill => skill?.content) : [];
    } catch(e) {
        agentSkillLibraryCache = [];
    }
    return agentSkillLibraryCache;
}
function agentSkillFavorites(){
    try {
        const parsed = JSON.parse(localStorage.getItem(AGENT_SKILL_FAVORITES_KEY) || '[]');
        return new Set(Array.isArray(parsed) ? parsed.filter(id => typeof id === 'string') : []);
    } catch(e) {
        return new Set();
    }
}
function setAgentSkillFavorite(id, favorite){
    const favorites = agentSkillFavorites();
    if(favorite) favorites.add(id);
    else favorites.delete(id);
    try {
        localStorage.setItem(AGENT_SKILL_FAVORITES_KEY, JSON.stringify([...favorites]));
        return true;
    } catch(e) {
        toast('收藏 Skill 失败，请检查浏览器存储空间');
        return false;
    }
}
async function loadCurrentAgentSkillLibrary(force=false){
    if(agentSkillLibraryLoaded && !force) return agentSkillLibrary();
    if(agentSkillLibraryLoading && !force) return agentSkillLibraryLoading;
    agentSkillLibraryLoading = (async () => {
        const response = await fetch('/api/agent-skills', {cache:'no-store'});
        if(!response.ok) throw new Error(`Skill API ${response.status}`);
        const data = await response.json();
        const items = Array.isArray(data?.skills) ? data.skills : [];
        agentSkillLibraryCache = items.map(skill => ({
            id:String(skill.id || ''),
            name:String(skill.name || skill.id || 'Skill'),
            description:String(skill.description || ''),
            updatedAt:Number(skill.updated_at || 0),
            source:'current-library'
        })).filter(skill => skill.id);
        agentSkillLibraryLoaded = true;
        // 当前库是唯一来源：画布里残留的旧 Skill 不再继续挂在 Agent 节点上。
        const allowed = new Set(agentSkillLibraryCache.flatMap(skill => [skill.id, skill.name]).filter(Boolean));
        let removedLegacy = false;
        nodes.forEach(node => {
            if(!['smart-agent', 'smart-prompt'].includes(node?.type) || !Array.isArray(node.installedSkills)) return;
            const next = node.installedSkills.filter(skill => allowed.has(skill?.id) || allowed.has(skill?.name));
            if(next.length !== node.installedSkills.length){
                node.installedSkills = next;
                removedLegacy = true;
            }
        });
        if(removedLegacy) scheduleSave();
        return agentSkillLibraryCache;
    })().catch(error => {
        console.warn('[Smart Canvas] 当前 Skill 库读取失败，保留本机缓存：', error);
        agentSkillLibraryLoaded = false;
        return agentSkillLibrary();
    }).finally(() => {
        agentSkillLibraryLoading = null;
    });
    return agentSkillLibraryLoading;
}
async function hydrateCurrentAgentSkill(skill){
    if(!skill || skill.content) return skill;
    if(skill.source !== 'current-library' || !skill.id) return skill;
    const response = await fetch(`/api/agent-skills/${encodeURIComponent(skill.id)}`, {cache:'no-store'});
    if(!response.ok) throw new Error(`Skill API ${response.status}`);
    const data = await response.json();
    return {...skill, content:String(data.instructions || '')};
}
function saveAgentSkillLibrary(skills){
    agentSkillLibraryCache = Array.isArray(skills) ? skills.filter(skill => skill?.content) : [];
    try {
        localStorage.setItem(AGENT_SKILL_LIBRARY_KEY, JSON.stringify(agentSkillLibraryCache));
        return true;
    } catch(e) {
        toast('Skill 内容过大，无法保存到本机 Skill 库');
        return false;
    }
}
function upsertAgentSkillLibrary(skill){
    if(!skill?.content) return null;
    const id = skill.id || uid('skill');
    const item = {...skill, id, savedAt:Date.now()};
    const library = agentSkillLibrary().filter(existing => existing.id !== id && existing.name !== item.name);
    library.unshift(item);
    return saveAgentSkillLibrary(library) ? item : null;
}
function openCanvasAgentSkillManager(){
    const panelEl = document.getElementById('canvasAgentPanel');
    const panelToggle = document.getElementById('canvasAgentToggle');
    const skillsToggle = document.getElementById('canvasAgentSkillsToggle');
    const skillPopover = document.getElementById('canvasAgentSkillPopover');
    if(!skillsToggle){
        toast('请从右下角 Agent 悬浮球打开 Skill 管理');
        return;
    }
    if(!panelEl?.classList.contains('open')) panelToggle?.click();
    window.setTimeout(() => {
        if(!skillPopover?.classList.contains('open')) skillsToggle.click();
        window.setTimeout(() => document.getElementById('canvasAgentSkillSearch')?.focus(), 0);
    }, 0);
}
window.openCanvasAgentSkillManager = openCanvasAgentSkillManager;
function renameAgentSkillLibraryItem(key, nextName){
    const name = String(nextName || '').trim().slice(0, 80);
    if(!name){
        toast('请输入 Skill 名称');
        return false;
    }
    const library = agentSkillLibrary();
    const item = library.find(skill => (skill.id || skill.name) === key);
    if(!item) return false;
    const previousName = item.name || 'Skill';
    const duplicated = library.some(skill => skill !== item && String(skill.name || '').trim().toLowerCase() === name.toLowerCase());
    if(duplicated){
        toast('已存在同名 Skill');
        return false;
    }
    item.name = name;
    if(!saveAgentSkillLibrary(library)) return false;
    nodes.forEach(candidate => {
        if(!['smart-agent', 'smart-prompt'].includes(candidate?.type)) return;
        candidate.installedSkills = agentSkills(candidate).map(skill => {
            const sameId = Boolean(item.id && skill.id === item.id);
            const sameName = Boolean(!item.id && skill.name === previousName);
            return sameId || sameName ? {...skill, name} : skill;
        });
    });
    return true;
}
