function scheduleSmartColorNodeRun(node, options={}){
    if(!isSmartColorNode(node)) return;
    const delay = options.immediate ? 0 : 220;
    if(node._colorRunTimer) clearTimeout(node._colorRunTimer);
    node._colorRunTimer = setTimeout(() => {
        node._colorRunTimer = 0;
        void runSmartColorNode(node.id, {force:Boolean(options.force)});
    }, delay);
}
async function runSmartColorNode(nodeId, options={}){
    const node = nodes.find(item => item.id === nodeId);
    if(!isSmartColorNode(node)) return false;
    normalizeSmartColorNode(node);
    const inputs = smartColorInputImages(node);
    if(!inputs.target?.url || !inputs.reference?.url) return false;
    const signature = smartColorInputSignature(node, inputs);
    if(!options.force && node.colorRunKey === signature && (node.images || []).some(image => image?.url)) return true;
    if(node.colorProcessing){
        node._colorRunQueued = true;
        return false;
    }
    if(typeof window.SmartColorNode?.process !== 'function'){
        node.colorError = '色彩处理模块未加载，请刷新画布后重试';
        node.colorErrorSignature = signature;
        render({nodeIds:[node.id]});
        scheduleSave();
        return false;
    }
    const requestId = uid('color-run');
    node.colorProcessing = true;
    node.colorError = '';
    node.colorRunRequestId = requestId;
    node.colorRunInputSignature = signature;
    render({nodeIds:[node.id]});
    scheduleSave();
    try {
        const result = await window.SmartColorNode.process({
            target:inputs.target,
            reference:inputs.reference,
            intensity:node.colorIntensity,
            preserveLuminance:node.preserveLuminance
        });
        if(node.colorRunRequestId !== requestId || smartColorInputSignature(node) !== signature){
            node.colorProcessing = false;
            node._colorRunQueued = true;
            render({nodeIds:[node.id]});
            scheduleSave();
            scheduleSmartColorNodeRun(node, {immediate:true, force:true});
            return false;
        }
        const sourceName = String(inputs.target.name || 'image').replace(/\.[^.]+$/, '').replace(/[\\/:*?"<>|]+/g, '_').slice(0, 80) || 'image';
        if(typeof window.SmartColorNode?.saveResult !== 'function'){
            throw new Error('色彩结果本地保存模块未加载，请刷新画布后重试');
        }
        const file = await window.SmartColorNode.saveResult(result.blob, {
            name:`${sourceName}_色彩还原.png`,
            width:result.width,
            height:result.height,
            derivedFrom:inputs.target.asset_ref_id || inputs.target.url,
            referenceFrom:inputs.reference.asset_ref_id || inputs.reference.url
        });
        if(!file?.url) throw new Error('色彩还原结果保存失败');
        if(node.colorRunRequestId !== requestId || smartColorInputSignature(node) !== signature){
            node.colorProcessing = false;
            node._colorRunQueued = true;
            render({nodeIds:[node.id]});
            scheduleSave();
            scheduleSmartColorNodeRun(node, {immediate:true, force:true});
            return false;
        }
        const previousColorResult = node.images?.[0];
        if(previousColorResult?._localBlobUrl && previousColorResult._localBlobUrl !== file.url){
            URL.revokeObjectURL(previousColorResult._localBlobUrl);
        }
        node.images = [{
            ...file,
            kind:file.kind || 'image',
            name:file.name || `${sourceName}_色彩还原.png`,
            natural_w:result.width || 0,
            natural_h:result.height || 0,
            derived_from:inputs.target.asset_ref_id || inputs.target.url,
            color_restored_from:inputs.reference.asset_ref_id || inputs.reference.url,
            local_db_id:file.local_db_id || '',
            local_storage:file.local_storage || 'session',
            _localBlobReady:file._localBlobReady === true,
            _localBlobUrl:file._localBlobUrl || file.url
        }];
        node.colorStorage = file.local_storage || 'session';
        delete node.colorLocalError;
        node.colorRunKey = signature;
        delete node.colorError;
        delete node.colorErrorSignature;
        node.colorProcessing = false;
        node._colorRunQueued = false;
        render({nodeIds:[node.id]});
        scheduleSave();
        return true;
    } catch(error){
        if(node.colorRunRequestId === requestId){
            node.colorProcessing = false;
            node.colorError = String(error?.message || '色彩还原失败').slice(0, 180);
            node.colorErrorSignature = signature;
            render({nodeIds:[node.id]});
            scheduleSave();
        }
        return false;
    } finally {
        if(node.colorRunRequestId === requestId) delete node.colorRunRequestId;
    }
}
