function openCreateMenu(event, options={}){
    if(!createMenu || !collabCanMutateCanvas(true)) return;
    if(createMenuCloseTimer){
        clearTimeout(createMenuCloseTimer);
        createMenuCloseTimer = 0;
    }
    createMenu.classList.remove('is-closing');
    createMenuPoint = options.point || screenToWorld(event);
    createMenuGroupId = options.groupId || '';
    pendingPortCreate = options.pendingConnection || null;
    // 画布直接打开时使用横向卡片；从连接点拖拽松开时保留紧凑竖向菜单。
    const compact = Boolean(options.pendingConnection);
    createMenu.classList.toggle('create-menu-compact', compact);
    const cards = [...createMenu.querySelectorAll('[data-create-type]')];
    cards.forEach((card, index) => {
        card.style.setProperty('--create-index', index);
        card.style.setProperty('--create-reverse-index', cards.length - index - 1);
    });
    const w = compact ? 188 : Math.max(188, Math.min(776, window.innerWidth - 28));
    const columns = window.innerWidth <= 720 ? 2 : 3;
    const rows = Math.ceil(cards.length / columns);
    const fallbackHeight = compact ? Math.max(170, cards.length * 44 + 16) : 32 + rows * 118 + Math.max(0, rows - 1) * 9;
    createMenu.style.left = '0px';
    createMenu.style.top = '0px';
    createMenu.classList.add('open');
    const menuWidth = createMenu.offsetWidth || w;
    const menuHeight = createMenu.offsetHeight || fallbackHeight;
    const pointerX = Number(event?.clientX) || 0;
    const pointerY = Number(event?.clientY) || 0;
    const left = Math.max(14, Math.min(window.innerWidth - menuWidth - 14, pointerX + 10));
    const top = Math.max(14, Math.min(window.innerHeight - menuHeight - 14, pointerY + 10));
    createMenu.style.left = `${left}px`;
    createMenu.style.top = `${top}px`;
    refreshIcons();
}
